type Fn = (x: number) => number;

const STEPS: Record<string, Fn> = {
  inc: x => x + 1,
  dec: x => x - 1,
  double: x => 2 * x,
  neg: x => -x,
};

function compose(fns: Fn[]): Fn {
  return x => fns.reduceRight((acc, f) => f(acc), x);
}

function composeRun(names: string[], xs: number[]): number[] {
  const composed = compose(names.map(n => STEPS[n]));
  return xs.map(composed);
}

