class Solution:
    STEPS = {
        "inc": lambda x: x + 1,
        "dec": lambda x: x - 1,
        "double": lambda x: 2 * x,
        "neg": lambda x: -x,
    }

    def compose(self, fns):
        def composed(x):
            for f in reversed(fns):
                x = f(x)
            return x
        return composed

    def composeRun(self, names: List[str], xs: List[int]) -> List[int]:
        composed = self.compose([self.STEPS[n] for n in names])
        return [composed(x) for x in xs]

