class Solution:
    STEPS = {
        "inc": lambda x: x + 1,
        "dec": lambda x: x - 1,
        "double": lambda x: 2 * x,
        "neg": lambda x: -x,
    }

    def compose(self, fns):
        composed = lambda x: x
        for f in fns:
            # bind outer and f now; a bare closure would see the last values
            composed = (lambda outer, g: lambda x: outer(g(x)))(composed, f)
        return composed

    def composeRun(self, names: List[str], xs: List[int]) -> List[int]:
        composed = self.compose([self.STEPS[n] for n in names])
        return [composed(x) for x in xs]

